package com.settlex.dto;

import java.math.BigDecimal;

/**
 * A single optimized payment instruction: {@code from} pays {@code amount} to {@code to}.
 *
 * <p>Generated by an engine; never supplied by clients. Amounts are always exact at two
 * decimal places.</p>
 *
 * @param from   the paying party (always a net debtor)
 * @param to     the receiving party (always a net creditor)
 * @param amount strictly positive payment value
 */
public record Settlement(String from, String to, BigDecimal amount) {

    /** Total cash moved by this instruction. */
    public BigDecimal cashFlow() {
        return amount;
    }
}